const catOf=c=>{c=String(c||'');if(/suppe|soup/i.test(c))return 'Soup';if(/dessert|nachtisch/i.test(c))return 'Desserts';if(/food ?truck/i.test(c))return 'Foodtruck';if(/beilage|side/i.test(c))return 'Sides';return 'Mains'};
