data.menus=data.menus||{};data.votes=data.votes||{};data.tr=data.tr||{};
data.cfg=data.cfg||{open:'11:00',close:'16:00',minVotes:10,flopPct:50};
const norm=m=>{const info=(m.notes||[]).join(' ')+' '+(m.category||'');return{key:keyOf(m.name),de:m.name,name:data.tr[m.name]||m.name,category:catOf(m.category),price:m.prices&&m.prices.students!=null?m.prices.students:null,diet:/vegan/i.test(info)?'vegan':/vegetar/i.test(info)?'vegetarian':'',notes:(m.notes||[]).join(', ')}};
async function fetchMenus(ctx){const days=await ctx.helpers.httpRequest({method:'GET',url:'https://openmensa.org/api/v2/canteens/277/meals',json:true});for(const d of days||[]){if(d.closed||!d.meals||!d.meals.length)continue;data.menus[d.date]={date:d.date,source:'OpenMensa',meals:d.meals.map(norm)}}data.fetchedDay=today;}
function tallies(){const t={};for(const[d,us]of Object.entries(data.votes)){const x=t[d]={};for(const v of Object.values(us))for(const[k,s]of Object.entries(v)){x[k]=x[k]||{up:0,down:0};if(s===1)x[k].up++;else if(s===-1)x[k].down++}}return t}

// GET /webhook/mensa?uid=...  -> everything the page needs
if(!data.menus[today]&&data.fetchedDay!==today){try{await fetchMenus(this)}catch(e){}}
const q=$input.first().json.query||{};const uid=String(q.uid||'').slice(0,64);
const keep=Object.keys(data.menus).sort().slice(-14);
const menus={};for(const d of keep){const m=data.menus[d];menus[d]={...m,meals:m.meals.map(x=>({...x,name:data.tr[x.de]||x.name}))}}
for(const d of Object.keys(data.votes).sort().slice(0,-60))delete data.votes[d];
const t=tallies();const mine={};for(const[d,us]of Object.entries(data.votes))if(uid&&us[uid])mine[d]=us[uid];
return [{json:{today,menus,tallies:t,mine,advice:data.advice||null,cfg:data.cfg}}];

