let error='';
if(!/^[\w-]{8,64}$/.test(uid))error='Missing reviewer id';
else if(date!==today)error="You can only review today's meal";
else if(!demo&&(mins<toMin(data.cfg.open)||mins>=toMin(data.cfg.close)))error='Reviews are closed right now';
else if(![1,-1,0].includes(v))error='Unknown vote';
else if(!/^[a-z0-9-]+$/.test(key))error='Unknown dish';
if(!error){const day=data.votes[date]=data.votes[date]||{};const u=day[uid]=day[uid]||{};if(v===0)delete u[key];else u[key]=v;}
const t=tallies();
return [{json:{ok:!error,error,tally:t[date]||{},mine:(data.votes[date]||{})[uid]||{}}}];

