// After lunch: today's results, dishes to drop, and a prompt for world dish ideas
if(!data.menus[today]){try{await fetchMenus(this)}catch(e){}}
const m=data.menus[today]||data.menus[Object.keys(data.menus).sort().pop()];
const t=tallies();
const per={};for(const x of Object.values(t))for(const[k,v]of Object.entries(x)){const s=per[k]=per[k]||{up:0,down:0};s.up+=v.up;s.down+=v.down}
const names={};for(const mm of Object.values(data.menus))for(const x of mm.meals)names[x.key]=data.tr[x.de]||x.name;
const flops=Object.entries(per).map(([k,s])=>({name:names[k]||k,n:s.up+s.down,pct:Math.round(s.down/Math.max(1,s.up+s.down)*100)})).filter(r=>r.n>=data.cfg.minVotes&&r.pct>=data.cfg.flopPct).sort((a,b)=>b.pct-a.pct);
const todayRes=(m?m.meals:[]).map(x=>{const v=(t[today]||{})[x.key]||{up:0,down:0};return{name:data.tr[x.de]||x.name,up:v.up,down:v.down}});
const prompt=`You advise the kitchen of a German university canteen (Mensa am Bildungscampus, Heilbronn, run by Studierendenwerk Heidelberg). The campus is international: students come from India, China, Turkey, the Middle East, Africa, Latin America, Eastern Europe and more.
Menu: ${JSON.stringify((m?m.meals:[]).map(x=>({name:data.tr[x.de]||x.name,category:x.category,diet:x.diet})))}
The kitchen has limited ingredients: only what these dishes clearly contain, plus pantry basics (oil, salt, pepper, onions, garlic, flour, sugar, common dried spices, stock).
Dishes students rejected and the kitchen should replace: ${JSON.stringify(flops.map(f=>f.name))}
Suggest 5 dishes from 5 different countries on at least 4 continents that can be cooked for 300+ portions mostly from these ingredients. At least 3 must be vegan or vegetarian. Where it fits, set "replaces" to a rejected dish the idea could replace, else "". Write in English.
Reply with JSON only: {"ingredients":[up to 12 key ingredients on hand],"ideas":[{"dish":"","country":"","region":"","diet":"vegan|vegetarian|with meat","uses":["ingredients from the menu"],"extra":["at most 3 small additions to buy"],"method":["3-4 short steps"],"batchTip":"one sentence for large-batch cooking","replaces":""}]}`;
return [{json:{today,flops,todayRes,body:{model:'claude-sonnet-5-5',max_tokens:3000,messages:[{role:'user',content:prompt}]}}}];

// Save the ideas for the app and build the kitchen e-mail
const data=$getWorkflowStaticData('global');
const prep=$('Results and prompt').first().json;
const r=$input.first().json;
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
let advice=null;
try{const txt=(r.content||[]).map(c=>c.text||'').join('');const j=JSON.parse(txt.slice(txt.indexOf('{'),txt.lastIndexOf('}')+1));
 advice={date:prep.today,source:'n8n + Claude',updatedAt:new Date().toISOString(),ingredients:(j.ingredients||[]).map(String).slice(0,14),ideas:(j.ideas||[]).slice(0,6)};data.advice=advice}catch(e){}
const rows=prep.todayRes.map(x=>`<tr><td>${esc(x.name)}</td><td align="right">${x.up}</td><td align="right">${x.down}</td></tr>`).join('');
const html=`<h2>Mensa Bildungscampus: kitchen report ${esc(prep.today)}</h2>
<h3>Today's reviews</h3><table border="1" cellpadding="6" cellspacing="0"><tr><th>Dish</th><th>Loved it</th><th>Not again</th></tr>${rows}</table>
<h3>Stop cooking these</h3><ul>${prep.flops.map(f=>`<li>${esc(f.name)}: ${f.pct}% not again (${f.n} reviews)</li>`).join('')||'<li>No dish has flopped yet.</li>'}</ul>
<h3>World kitchen ideas</h3><ol>${advice?advice.ideas.map(i=>`<li><b>${esc(i.dish)}</b> (${esc(i.country)})${i.replaces?' could replace '+esc(i.replaces):''}. ${esc(i.batchTip)}</li>`).join(''):'<li>No ideas: check the Anthropic credential.</li>'}</ol>`;
return [{json:{subject:`Mensa kitchen report ${prep.today}`,html,ideas:advice?advice.ideas.length:0}}];
